head.b:skin:
      body {
        font-family: Arial, sans-serif;
        background: #000;
        color: #fff;
        margin: 0;
        padding: 0;
      }

      /* Header Sticky Jumbo */
      .header {
        position: sticky;
        top: 0;
        z-index: 1000;
        background-color: #111;
        padding: 45px 20px;
        display: flex;
        justify-content: center;
        gap: 20px;
        border-bottom: 2px solid #444;
      }
      .header a {
        background-color: #444;
        color: white;
        padding: 24px 50px;
        font-size: 30px;
        font-weight: bold;
        border-radius: 12px;
        text-decoration: none;
        display: inline-block;
      }
      .header a:hover {
        background-color: #666;
      }

      /* Grid Container */
      .grid-container {
        display: grid;
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
        width: 100%;
        padding: 10px;
        box-sizing: border-box;
      }
      .grid-item {
        text-align: center;
        padding: 10px;
        border: 1px solid #444;
        border-radius: 5px;
        background-color: #111;
        position: relative;
        cursor: pointer;
        overflow: hidden;
      }
      .grid-item img {
        width: 100%;
        height: auto;
        display: block;
        border-radius: 5px;
      }
      .grid-item p {
        font-size: 22px;
        font-weight: bold;
        margin-top: 8px;
        color: #fff;
      }
      a {
        color: #fff;
      }
      a:hover {
        text-decoration: underline;
      }

      /* Overlay Video */
      .video-overlay {
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: rgba(0,0,0,0.5);
        display: flex;
        align-items: center;
        justify-content: center;
        opacity: 0;
        pointer-events: none; /* biar ga ganggu klik link */
        transition: opacity 0.3s ease;
      }
      .video-overlay.show {
        opacity: 1;
        pointer-events: auto;
      }

/* Posisi vertikal */
.video-overlay.top {
  align-items: flex-start;   /* atas */
}
.video-overlay.center {
  align-items: center;       /* tengah */
}
.video-overlay.bottom {
  align-items: flex-end;     /* bawah */
}



      /* Ikon Play */
      .play-icon {
        width: 70px;
        height: 70px;
        background: rgba(255,255,255,0.9);
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
      }
      .play-icon:before {
        content: '';
        display: block;
        width: 0;
        height: 0;
        border-left: 20px solid #000;
        border-top: 12px solid transparent;
        border-bottom: 12px solid transparent;
      }

      /* Sembunyikan garis bawah link dalam grid-item */
      .grid-item a,
      .grid-item a:link,
      .grid-item a:visited,
      .grid-item a:hover,
      .grid-item a:active {
        text-decoration: none !important;
        color: inherit;
      }

      /* Tombol halaman */
      .pagination {
        display: flex;
        justify-content: center;
        gap: 20px;
        margin: 20px 0;
      }
      .page-btn {
        background-color: #ff7f00;
        color: #fff;
        padding: 12px 25px;
        text-decoration: none;
        font-weight: bold;
        border-radius: 8px;
        transition: background-color 0.3s ease;
      }
      .page-btn:hover {
        background-color: #ff9900;
      }

  /* Tambah */
 .thumbnail {
  position: relative;
  width: 100%;
  overflow: hidden;
  border-radius: 5px;
}

.video-title {
  font-size: 20px;
  font-weight: bold;
  margin-top: 10px;
  color: #fff;
  text-align: center;
}

