            Iklan ini akan otomatis menutup dalam **2** detik.





/**/
    var iklanHitam = document.getElementById('modal-iklan-hitam');
    var timerOtomatis;
    var hitunganMundurInterval;

    function tutupIklanHitam() {
        if (!iklanHitam) return; 
        iklanHitam.style.opacity = '0';
        clearInterval(hitunganMundurInterval); // Hentikan hitungan mundur saat iklan ditutup
        clearTimeout(timerOtomatis); // Hentikan timer penutup otomatis
        setTimeout(function() {
            iklanHitam.style.display = 'none';
        }, 300); 
    }

    function mulaiHitunganMundur() {
        var detikSaatIni = 4; // Mulai dari 4
        var timerDisplay = document.getElementById('countdown-timer');

        // Ganti angka 4 di teks awal
        if (timerDisplay) {
            timerDisplay.innerHTML = 'Iklan ini akan otomatis menutup dalam <strong>' + detikSaatIni + '</strong> detik.';
        }

        // Fungsi yang dijalankan setiap 1 detik
        hitunganMundurInterval = setInterval(function() {
            detikSaatIni--;

            if (timerDisplay) {
                if (detikSaatIni > 0) {
                     timerDisplay.innerHTML = 'Iklan ini akan otomatis menutup dalam <strong>' + detikSaatIni + '</strong> detik.';
                } else {
                     timerDisplay.textContent = 'Iklan ditutup.';
                }
            }

            // Hentikan interval jika mencapai 0
            if (detikSaatIni <= 0) {
                clearInterval(hitunganMundurInterval);
            }
        }, 1000); // 1000ms = 1 detik
    }

    function initIklan() {
        if (!iklanHitam) return;

        // Pasang event listener pada tombol tutup
        var closeButton = document.querySelector('#modal-iklan-hitam .tutup-iklan-merah');
        if (closeButton) {
             closeButton.addEventListener('click', tutupIklanHitam);
        }

        // Tampilkan iklan
        iklanHitam.style.display = 'block';
        setTimeout(function() {
            iklanHitam.style.opacity = '1';
        }, 10);

        // Mulai hitungan mundur (5,3,4,2, 1, 0)
        mulaiHitunganMundur();

        // Iklan hilang otomatis setelah 2 detik (4000 milidetik)
        timerOtomatis = setTimeout(tutupIklanHitam, 4000); 
    }

    // Jalankan inisialisasi setelah DOM siap
    window.addEventListener('load', initIklan);
/**/














