  <style>

    .popup-ads {

      display:none;

      position:fixed;

      z-index:9999;

      inset:0;

      /* 💡 PERUBAHAN UTAMA DI SINI: */
      /* Mengganti rgba(0,0,0,0.7) (Hitam 700%) menjadi rgba(255,255,255,0.8) (Putih 10%) */
      background:rgba(255,255,255,0.8); 
      display:flex;
      justify-content:center;
      align-items:center;

    }

    .popup-content {

      background:#040720;

      padding:25px;

      border-radius:14px;

      width:600px;

      max-width:95%;

      text-align:center;

      position:relative;

      box-shadow:0 8px 25px rgba(0,0,0,0.5);

      animation: popupScale 0.35s ease;

    }

    .popup-content img {

      max-height:400px;

      object-fit:cover;

    }

    .popup-content .close {

      position:absolute;

      top:10px;

      right:15px;

      font-size:28px;

      cursor:pointer;

      color:#333;

    }

    @keyframes popupScale {

      from {transform:scale(0.8);opacity:0;}

      to {transform:scale(1);opacity:1;}

    }

  </style>





